from gurobipy import Model, GRB, quicksum
import sys

def FJSPModel(job_count, MacNum, OpNum, M_table, pt_table, M, X, Y, B):
    model = Model("FJSP_PPF")
    C_max = model.addVar(lb=0, ub=M, vtype="I", name="C_max")

    # Define variables
    # Define 0-1 decision variable Y[i,j,i',j']
    for i in range(job_count):
        for i_prime in range(job_count):
            for j in range(OpNum[i]):
                for j_prime in range(OpNum[i_prime]):
                    Y[i, j, i_prime, j_prime] = model.addVar(lb=0, ub=1, vtype="I", name=f"Y({i},{j},{i_prime},{j_prime})")

    # Define continuous decision variable B[i,j]
    for i in range(job_count):
        for j in range(OpNum[i]):
            B[i, j] = model.addVar(lb=0, vtype="C", name=f"B({i},{j})")

    # Define 0-1 decision variable X[i,j,k]
    for i in range(job_count):
        for j in range(OpNum[i]):
            for k in range(MacNum):
                X[i, j, k] = model.addVar(lb=0, ub=1, vtype="B", name=f"X({i},{j},{k})")

    # Objective function
    model.setObjective(C_max, GRB.MINIMIZE)

    # Constraint (1)
    for i in range(job_count):
        for j in range(OpNum[i]):
            model.addConstr(quicksum(X[i, j, k] for k in range(MacNum) if M_table[i][j][k] > 0) == 1, "assignment(%s,%s)" % (i, j))

    # Constraint (2)
    for i in range(job_count):
        for j in range(OpNum[i] - 1):
            model.addConstr(B[i, j] + quicksum(pt_table[i, j, k] * X[i, j, k] for k in range(MacNum) if M_table[i][j][k] > 0) <= B[i, j + 1], "predecessor(%s,%s)" % (i, j))

    # Constraint (3)
    for i in range(job_count):
        for i_prime in range(i + 1, job_count):
            for j in range(OpNum[i]):
                for j_prime in range(OpNum[i_prime]):
                    for k in range(MacNum):
                        if M_table[i][j][k] > 0 and M_table[i_prime][j_prime][k] > 0:
                            model.addConstr(B[i, j] + pt_table[i, j, k] * X[i, j, k] <= B[i_prime, j_prime] + M * (3 - Y[i, j, i_prime, j_prime] - X[i, j, k] - X[i_prime, j_prime, k]), "constraint3(%s,%s,%s,%s,%s)" % (i, j, i_prime, j_prime, k))

    # Constraint (3)
    for i in range(job_count):
        for i_prime in range(i + 1, job_count):
            for j in range(OpNum[i]):
                for j_prime in range(OpNum[i_prime]):
                    for k in range(MacNum):
                        if M_table[i][j][k] > 0 and M_table[i_prime][j_prime][k] > 0:
                            model.addConstr(B[i_prime, j_prime] + pt_table[i_prime, j_prime, k] * X[i_prime, j_prime, k] <= B[i, j] + M * (2 + Y[i, j, i_prime, j_prime] - X[i, j, k] - X[i_prime, j_prime, k]), "constraint4(%s,%s,%s,%s,%s)" % (i, j, i_prime, j_prime, k))

    # Constraint (4)
    for i in range(job_count):
        for j in range(OpNum[i]):
            model.addConstr(B[i, j] + quicksum(pt_table[i, j, k] * X[i, j, k] for k in range(MacNum) if M_table[i][j][k] > 0) <= C_max, "finish_time(%s,%s)" % (i, j))

    # Constraint (5)
    for i in range(job_count):
        for j in range(OpNum[i]):
            model.addConstr(B[i, j] >= 0, "non_negative_start_time(%s,%s)" % (i, j))

    # Constraint 6: Job 1 must not begin processing before time 500; starting exactly at 500 is allowed.
    model.addConstr(B[0, 0] >= 500, name="start_time_lower_bound_1")
    # Constraint 6: Job 2 must be completed no later than time 2000, including completion at 2000.
    model.addConstr(B[1, OpNum[1]-1] + quicksum(pt_table[1, OpNum[1]-1, k] * X[1, OpNum[1]-1, k] for k in range(MacNum) if M_table[1, OpNum[1]-1][k] > 0) <= 2000, name="job2_completion_ub")
    # Constraint 6: To allow natural cooling and curing after adhesive application, the waiting interval from the completion of an operation to the start of the next operation must be between 25 and 55 time units for every job, inclusive.
    for i in range(job_count):
        for j in range(OpNum[i] - 1):
            model.addConstr(B[i, j + 1] >= B[i, j] + quicksum(pt_table[i, j, k] * X[i, j, k] for k in range(MacNum) if M_table[i][j][k] > 0) + 25, name=f"wait_lb_25({i},{j})")
            model.addConstr(B[i, j + 1] <= B[i, j] + quicksum(pt_table[i, j, k] * X[i, j, k] for k in range(MacNum) if M_table[i][j][k] > 0) + 55, name=f"wait_ub_55({i},{j})")
    # Constraint 6: To respect the material loading order, the first operation of Job 1 must start no later than the first operation of Job 2. They may start at the same time.
    model.addConstr(B[0, 0] <= B[1, 0], name="job1_start_before_job2_due_to_loading")
    # Constraint 6: On every machine, if consecutive operations belong to different jobs, the later operation must start at least 50 time units after the earlier operation finishes.
    for k in range(MacNum):
        for i in range(job_count):
            for i_prime in range(job_count):
                if i == i_prime:
                    continue
                for j in range(OpNum[i]):
                    for j_prime in range(OpNum[i_prime]):
                        if M_table[i][j][k] > 0 and M_table[i_prime][j_prime][k] > 0:
                            model.addConstr(
                                B[i, j] + pt_table[i, j, k] * X[i, j, k] + 50 <= B[i_prime, j_prime] + M * (3 - Y[i, j, i_prime, j_prime] - X[i, j, k] - X[i_prime, j_prime, k]),
                                name=f"delay_setup1({i},{j},{i_prime},{j_prime},{k})"
                            )
                            model.addConstr(
                                B[i_prime, j_prime] + pt_table[i_prime, j_prime, k] * X[i_prime, j_prime, k] + 50 <= B[i, j] + M * (2 + Y[i, j, i_prime, j_prime] - X[i, j, k] - X[i_prime, j_prime, k]),
                                name=f"delay_setup2({i},{j},{i_prime},{j_prime},{k})"
                            )
    # Constraint 6: For every job, if two consecutive operations are assigned to different machines, at least 45 time units must elapse after the earlier operation finishes before the next operation starts, to allow transportation.
    for i in range(job_count):
        for j in range(OpNum[i] - 1):
            same_machine = quicksum(X[i, j, k] * X[i, j+1, k] for k in range(MacNum) 
                                  if M_table[i][j][k] > 0 and M_table[i][j+1][k] > 0)
            model.addConstr(
                B[i, j+1] >= B[i, j] + quicksum(pt_table[i, j, k] * X[i, j, k] 
                                              for k in range(MacNum) if M_table[i][j][k] > 0) 
                            + 45 * (1 - same_machine),
                name=f"transport_delay_45({i},{j})"
            )

    # Set parameters
    model.params.TimeLimit = 100
    model.setParam('Threads', 20)
    model.update()

    return model

