    for i in range(job_count):
        for i_prime in range(i + 1, job_count):
            for j in range(OpNum[i]):
                for j_prime in range(OpNum[i_prime]):
                    k = 4  # Machine 5 (Python index 4)
                    if M_table[i][j][k] > 0 and M_table[i_prime][j_prime][k] > 0:
                        model.addConstr(
                            B[i, j] + pt_table[i, j, k] * X[i, j, k] + 60 <= B[i_prime, j_prime] + M * (3 - Y[i, j, i_prime, j_prime] - X[i, j, k] - X[i_prime, j_prime, k]),
                            name=f"machine5_setup1({i},{j},{i_prime},{j_prime})"
                        )
                        model.addConstr(
                            B[i_prime, j_prime] + pt_table[i_prime, j_prime, k] * X[i_prime, j_prime, k] + 60 <= B[i, j] + M * (2 + Y[i, j, i_prime, j_prime] - X[i, j, k] - X[i_prime, j_prime, k]),
                            name=f"machine5_setup2({i},{j},{i_prime},{j_prime})"
                        )
    # Constraint 6: For Job 2, whenever consecutive operations are assigned to different machines, the next operation must start at least 35 time units after the preceding operation finishes to allow transportation.
    i = 1  # Job 2 (Python index 1)
    for j in range(OpNum[i] - 1):
        same_machine = quicksum(X[i, j, k] * X[i, j+1, k] for k in range(MacNum) 
                          if M_table[i][j][k] > 0 and M_table[i][j+1][k] > 0)
        model.addConstr(
            B[i, j+1] >= B[i, j] + quicksum(pt_table[i, j, k] * X[i, j, k] 
                                          for k in range(MacNum) if M_table[i][j][k] > 0) 
                        + 35 * (1 - same_machine),
            name=f"job2_transport_delay_35({j})"
        )

    # Set parameters
    model.params.TimeLimit = 100
    model.setParam('Threads', 20)
    model.update()

    return model
